set-variable.value:
@{
				var body = (JObject)context.Variables["request-body"];
				var route = ((string)context.Variables["route"]).Split('|');
				var size = System.Text.Encoding.UTF8.GetByteCount(context.Request.Body.As<string>(preserveContent: true));
				if (size > long.Parse(route[3]) * 1024) { return "413|request_too_large"; }
				foreach (var p in "{{forbidden-parameters}}".Split(',')) {
					if (p != "" && body[p] != null) { return "400|parameter_not_allowed"; }
				}
				var allowedTools = "{{allowed-tool-types}}".Split(',');
				var tools = body["tools"] as JArray;
				if (tools != null) {
					foreach (var t in tools) {
						if (!allowedTools.Contains(t["type"]?.ToString() ?? "")) { return "400|tool_not_allowed"; }
					}
				}
				return "";
			}

@{
				var s = ((JObject)context.Variables["request-body"])["stream"];
				return s != null && s.Type == JTokenType.Boolean && (bool)s && ((string)context.Variables["route"]).Split('|')[5] == "chat";
			}

when.set-body:
@{
				var body = (JObject)context.Variables["request-body"];
				var route = ((string)context.Variables["route"]).Split('|');
				var cap = int.Parse(route[2]);
				body["model"] = route[1];
				if (route[5] == "embedding") { return body.ToString(Newtonsoft.Json.Formatting.None); }
				var requested = body["max_output_tokens"];
				if (requested == null || requested.Type != JTokenType.Integer || (int)requested > cap) { body["max_output_tokens"] = cap; }
				return body.ToString(Newtonsoft.Json.Formatting.None);
			}
